      const out = {}, T = rowsOf(table, src[table]);
      for (const id of Object.keys(T)) {
        const row = T[id];
        if (!rowExists(table, id)) { dropped++; continue; }
        if (table === 'names') {
          if (!Array.isArray(row)) { dropped++; continue; }
