  await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
  await page.mouse.down(); await page.waitForTimeout(ms); await page.mouse.up();
}
export async function answerGate(page, right = true) {
  const q = await page.locator('#gateQ').textContent(), [a, b] = q.match(/\d+/g).map(Number);
  await page.fill('#gateIn', String(right ? a * b : a * b + 1)); await page.click('#gateOk');
}
export async function openSettings(page) {
  await holdGear(page); await page.locator('#gateQ').waitFor(); await answerGate(page);
  await page.locator('#grown .gpanel').waitFor();
}
export const tab = (page, k) => page.click(`[data-gtab="${k}"]`);
// open a row of the settings (its fields show), by its table and id
export async function row(page, table, id) {
  const d = page.locator(`details[data-row="${table}|${id}"]`);
  if ((await d.getAttribute('open')) === null) await d.locator('summary').click();
  return d;
}
export const fieldIn = (page, table, id, f, kind = 'text') => page.locator(`#grown input[data-k="${kind}"][data-t="${table}"][data-id="${id}"][data-f="${f}"]`);
export async function type(page, table, id, f, value, kind = 'text') { const el = fieldIn(page, table, id, f, kind); await el.fill(String(value)); await el.press('Enter'); }
// close the screen: the game reloads with the settings applied
export async function closeSettings(page) {
  await Promise.all([page.waitForEvent('load'), page.click('#gClose')]);
  await ready(page);
}
export const settingsFile = (page) => page.evaluate(() => JSON.parse(JSON.stringify(window.__game.settings.file)));
export async function shot(page, name) { if (!SHOTS) return; await mkdir(SHOTS, { recursive: true }); await page.screenshot({ path: join(SHOTS, `${name}.png`) }); }
// the toast's words, once it says something matching
export async function toastSays(page, re) {
  await page.waitForFunction((src) => new RegExp(src).test(document.querySelector('#toast').textContent), re.source, { timeout: 10000 });
  return page.locator('#toast').textContent();
}
];
export const seasonRules = (season) => ({
  season, parking: season >= 2, floors: season >= 3, moods: season >= 3,
  classes: CLASSES.filter((c) => c.from <= season).map((c) => c.id),
});
// the stars a new school starts with
export const START = { stars: 30 };

/* ---------------- the rows a grown-up may change ---------------- */
// Everything above is the default game. applyRows(over) lays changed rows over it, in place, before the game starts:
//   { moves: { plie: { fr: 'Plié royal' } }, outfits: { fee: { price: 20 } }, start: { stars: 50 } }
// A row that exists gets the given fields; a new id adds a row (it must carry every field its table's rows have);
// nothing is removed. Every module reads these same objects, so a change reaches the rules, the 3D and the sheet alike.
// WHERE the changes are kept between visits is the page's business, not this file's.
const ROW_TABLES = { classes: CLS, names: NAMES, numbers: NUMBERS, moves: MOVES, outfits: OUTFITS, hairs: HAIRS, shoes: SHOES, accs: ACCS, pieces: PIECES, snacks: SNACKS, upgrades: UPGRADES };
const ONE_ROW = { rules: RULES, start: START, parking: PARKING };
export const EDITABLE = [...Object.keys(ROW_TABLES), ...Object.keys(ONE_ROW)];
export function applyRows(over = {}) {
  for (const [t, rows] of Object.entries(over)) {
    if (ONE_ROW[t]) { Object.assign(ONE_ROW[t], rows); continue; }
    const T = ROW_TABLES[t]; if (!T) throw new Error(`applyRows: no table "${t}" (tables: ${EDITABLE.join(', ')})`);
    for (const [id, row] of Object.entries(rows)) {
      if (Array.isArray(row) || !T[id] || typeof T[id] !== 'object' || Array.isArray(T[id])) T[id] = row;
      else Object.assign(T[id], row);
      if (t === 'classes' && !CLASSES.includes(T[id])) CLASSES.push(T[id]);
    }
  }
}
// Change 001, the grown-ups' settings, line by line (changes/001-grown-up-settings.md), driven like a player: real
// clicks, a real long press, the sum typed in. Each test has its own server and its own settings folder.
import test, { before, after } from 'node:test';
import assert from 'node:assert/strict';
import { writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { startServer, launch, openGame, holdGear, answerGate, openSettings, tab, row, fieldIn, type, closeSettings, settingsFile, shot, toastSays } from './helpers.mjs';

let browser; const servers = [];
before(async () => { browser = await launch(); });
after(async () => { await browser.close(); await Promise.all(servers.map((s) => s.stop())); });
// each test starts from nothing; the last test's pages are closed (three games drawing at once slow everything down)
async function fresh(opts) {
  for (const c of browser.contexts()) await c.close();
  const s = await startServer(); servers.push(s); const page = await openGame(browser, s.url, opts); return { s, page };
}
const noErrors = (page) => assert.deepEqual(page.errors, [], page.errors.join('\n'));
const sheet = (page) => page.locator('#sbody').innerText();

test('1. When I tap the ⚙️ button quickly, the settings don\'t open: a note says it\'s for grown-ups', async () => {
  const { page } = await fresh();
  await page.click('#gearBtn');
  await page.waitForTimeout(300);
  assert.equal(await page.locator('#grown').count(), 0);
  assert.equal(await page.locator('#gate').count(), 0);
  assert.match(await page.locator('#toast').textContent(), /reste appuyé/);
  await shot(page, '1'); noErrors(page);
});

